<script setup lang="ts">
import { computed,nextTick,onBeforeUnmount,onMounted,ref } from 'vue'
import { useRouter } from 'vue-router'
import { init,use,type ECharts } from 'echarts/core'
import { LineChart } from 'echarts/charts'
import { GridComponent,LegendComponent,TooltipComponent } from 'echarts/components'
import { CanvasRenderer } from 'echarts/renderers'
import { api,errorText } from '../api/http'
import { useAuthStore } from '../stores/auth'
import { money,dateTime,statusLabel,sourceRoute } from '../utils/format'
import type { Row } from '../types'
import StatusTag from '../components/StatusTag.vue'
import NavIcon from '../components/NavIcon.vue'
use([LineChart,GridComponent,LegendComponent,TooltipComponent,CanvasRenderer])
const auth=useAuthStore(),router=useRouter(),data=ref<Row|null>(null),loading=ref(false),error=ref(''),dates=ref<string[]>([]),chartElement=ref<HTMLDivElement>()
let chart:ECharts|undefined,observer:ResizeObserver|undefined
const cards=computed(()=>{const c=data.value?.cards||{};return [{key:'purchaseCount',label:'采购订单数量',value:c.purchaseCount,icon:'purchase',note:'区间内创建 · 不含取消单',color:'blue'},{key:'salesCount',label:'销售订单数量',value:c.salesCount,icon:'sales',note:'区间内创建 · 不含取消单',color:'purple'},{key:'receivedPurchaseAmount',label:'已收货采购金额',value:c.receivedPurchaseAmount==null?undefined:'¥ '+money(c.receivedPurchaseAmount),icon:'inbound',note:'区间创建且已收货 · 人民币',color:'orange'},{key:'shippedSalesAmount',label:'已发货销售金额',value:c.shippedSalesAmount==null?undefined:'¥ '+money(c.shippedSalesAmount),icon:'outbound',note:'区间创建且已发货 · 人民币',color:'green'}].filter(c=>c.value!==undefined)})
const stages=['DRAFT','READY_TO_ISSUE','IN_PRODUCTION','PENDING_INBOUND','COMPLETED']
async function load(){loading.value=true;error.value='';try{data.value=(await api.get('/workbench',{params:{from:dates.value?.[0]?new Date(dates.value[0]).toISOString():undefined,to:dates.value?.[1]?new Date(dates.value[1]).toISOString():undefined}})).data;await nextTick();renderChart()}catch(e){error.value=errorText(e)}finally{loading.value=false}}
function renderChart(){if(!chartElement.value||!data.value)return;chart||=init(chartElement.value);observer?.observe(chartElement.value);const trend=data.value.trend||[],series=[];if(trend.some((d:Row)=>d.purchaseCount!==undefined))series.push({name:'采购订单',type:'line',smooth:true,symbolSize:6,data:trend.map((d:Row)=>Number(d.purchaseCount)),lineStyle:{width:2},areaStyle:{opacity:.045}});if(trend.some((d:Row)=>d.salesCount!==undefined))series.push({name:'销售订单',type:'line',smooth:true,symbolSize:6,data:trend.map((d:Row)=>Number(d.salesCount)),lineStyle:{width:2}});chart.setOption({animation:false,color:['#527fda','#8e9ebf'],tooltip:{trigger:'axis'},legend:{right:0,top:0,itemWidth:16,itemHeight:6,textStyle:{fontSize:11,color:'#8b97a9'}},grid:{left:42,right:15,top:48,bottom:32},xAxis:{type:'category',boundaryGap:false,data:trend.map((d:Row)=>d.date.slice(5)),axisLine:{lineStyle:{color:'#e9edf3'}},axisTick:{show:false},axisLabel:{color:'#96a1b1',fontSize:11}},yAxis:{type:'value',minInterval:1,axisLabel:{color:'#96a1b1',fontSize:11},splitLine:{lineStyle:{color:'#eff2f7',type:'dashed'}}},series},{notMerge:true});chart.resize()}
function goSource(order:Row){const target=sourceRoute(order.kind,order.id);if(target&&auth.can(target.permission))void router.push(target.path)}
onMounted(()=>{observer=new ResizeObserver(()=>chart?.resize());if(chartElement.value)observer.observe(chartElement.value);void load()})
onBeforeUnmount(()=>{observer?.disconnect();chart?.dispose()})
</script>
<template><div class="page-header dashboard-header"><div><h1>你好，{{auth.user?.displayName}}</h1></div><div class="dashboard-date"><el-date-picker v-model="dates" type="datetimerange" start-placeholder="统计起始时间" end-placeholder="统计结束时间" aria-label="工作台统计区间"/><el-button :loading="loading" @click="load">{{dates?.length?'应用区间':'刷新数据'}}</el-button></div></div><div v-if="error" class="error-box" role="alert">{{error}} <el-button link @click="load">重试</el-button></div><el-skeleton v-if="loading&&!data" :rows="8" animated/>
<div v-else v-loading="loading"><p v-if="data?.period" class="dashboard-range">统计区间 {{dateTime(data.period.from)}} — {{dateTime(data.period.to)}}<span>金额按单据创建时间筛选及业务状态统计，非收入或利润。</span></p><div class="metric-grid"><article v-for="card in cards" :key="card.key" class="metric-card"><div class="metric-top"><span>{{card.label}}</span><span class="metric-icon" :class="card.color"><NavIcon :name="card.icon"/></span></div><div class="metric-number number">{{card.value}}</div><div class="metric-note">{{card.note}}</div></article></div>
<div v-if="data?.cards?.confirmedPurchaseAmount!==undefined||data?.cards?.confirmedSalesAmount!==undefined" class="amounts-summary"><span v-if="data?.cards?.confirmedPurchaseAmount!==undefined">已确认及后续采购总额 <strong>¥ {{money(data.cards.confirmedPurchaseAmount)}}</strong></span><span v-if="data?.cards?.confirmedSalesAmount!==undefined">已确认及后续销售总额 <strong>¥ {{money(data.cards.confirmedSalesAmount)}}</strong></span></div><div class="dashboard-middle"><section class="panel trend-panel"><div class="panel-title"><div><h2>业务趋势</h2><p class="section-note">近 7 个上海自然日 · 新建订单数（单）</p></div><el-tag type="info" effect="plain" size="small">最近 7 天</el-tag></div><div ref="chartElement" class="trend-chart" role="img" aria-label="近7天真实采购和销售订单趋势"/><p v-if="data?.trend?.every((d:Row)=>!Number(d.purchaseCount)&&!Number(d.salesCount))" class="chart-empty">近 7 天暂无订单，开始第一笔业务吧</p><p v-if="!auth.can('erp:purchase:read')&&!auth.can('erp:sales:read')" class="section-note">当前账号没有订单统计查看权限。</p></section>
<section class="panel progress-panel"><div class="panel-title"><h2>生产进度</h2><router-link v-if="auth.can('mes:production:read')" to="/mes/production-orders" class="text-link">查看全部 →</router-link></div><div v-if="data?.production" class="production-distribution"><span v-for="state in data.production.byStatus" :key="state.status">{{statusLabel(state.status)}} <strong>{{state.count}}</strong></span><p class="completed-quantities">本期已完成：<template v-if="data.production.completedQuantities?.length"><span v-for="item in data.production.completedQuantities" :key="item.unit">{{item.quantity}} {{item.unit}} </span></template><span v-else>暂无完成数量</span></p></div><div v-if="data?.recentProduction?.length" class="production-list"><article v-for="order in data.recentProduction" :key="order.id"><div class="production-top"><button class="plain-link" @click="router.push(`/mes/production-orders/${order.id}`)">{{order.productName}}</button><StatusTag :value="order.status"/></div><div class="production-caption">{{order.plannedQuantity}} {{order.unit}}<span>{{order.orderNo}}</span></div><div class="stage-track" :aria-label="statusLabel(order.status)"><span v-for="(stage,index) in stages" :key="stage" :class="{done:order.status!=='CANCELLED'&&index<=stages.indexOf(order.status)}"/></div></article></div><el-empty v-else :image-size="65" :description="auth.can('mes:production:read')?'暂无生产工单':'暂无生产查看权限'"/></section></div>
<div class="dashboard-bottom"><section class="panel"><div class="panel-title"><h2>当前业务待办</h2><span class="section-note">实时状态</span></div><div v-if="data?.todos?.length" class="todo-list"><button v-for="todo in data.todos" :key="todo.type+'-'+todo.route" @click="router.push(todo.route)"><span class="todo-dot"/><span>{{todo.label}}</span><strong>{{todo.count}}</strong><span class="muted">→</span></button></div><el-empty v-else :image-size="60" description="暂无可执行待办"/><div v-if="data?.inventory" class="warning-summary"><div><span>库存预警</span><strong>{{data.inventory.lowStockCount}}</strong><span class="muted">个仓库物料维度</span></div><router-link to="/wms/balances?lowStockOnly=true">查看预警 →</router-link></div><div v-if="data?.inventory?.items?.length" class="warning-items"><div v-for="item in data.inventory.items.slice(0,3)" :key="item.warehouseId+item.materialId"><span>{{item.materialName}} <small>{{item.warehouseName}}</small></span><span>{{item.quantity}} / {{item.minStock}} {{item.unit}}</span></div></div></section>
<section class="panel recent-panel"><div class="panel-title"><h2>最新业务订单</h2><span class="section-note">当前最新 5 笔</span></div><el-table :data="data?.recentOrders||[]" empty-text="暂无采购或销售订单"><el-table-column label="业务单号" min-width="210"><template #default="{row}"><button class="plain-link order-link" @click="goSource(row)">{{row.orderNo}}</button><small class="order-kind">{{row.kind==='PURCHASE_ORDER'?'零部件采购':'整机销售'}}</small></template></el-table-column><el-table-column prop="partnerName" label="客户 / 供应商" min-width="150"/><el-table-column label="订单金额" align="right" width="145"><template #default="{row}">¥ {{money(row.totalAmount)}}</template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}"><StatusTag :value="row.status"/></template></el-table-column><el-table-column label="创建日期" width="150"><template #default="{row}">{{dateTime(row.createdAt).slice(0,10)}}</template></el-table-column></el-table></section></div><p class="section-note dashboard-note">数据来自当前数据库 · 订单与金额按各自权限展示 · 库存按物料和单位查看，不跨物料累加。</p></div></template>
<style scoped>.amounts-summary{display:flex;gap:28px;flex-wrap:wrap;font-size:11px;color:#8995a6;margin:-7px 0 22px}.amounts-summary strong{color:#536b90;font-weight:500;margin-left:9px}.production-distribution{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-bottom:10px;padding-bottom:12px;border-bottom:1px solid #edf0f4;font-size:11px;color:#8995a6}.production-distribution strong{color:#476a9b;margin-left:5px}.completed-quantities{grid-column:1/-1;margin:1px 0 0;font-size:10px}.dashboard-header{margin-bottom:17px}.dashboard-header h1{margin-top:10px;font-size:26px}.eyebrow{font-size:9px;letter-spacing:2px;color:#9aa7b9}.dashboard-date{display:flex;gap:10px}.dashboard-date .el-date-editor{max-width:315px}.dashboard-range{display:flex;justify-content:space-between;gap:10px;font-size:10px;color:#a2acb9;margin-bottom:18px}.metric-card{background:#fff;border:1px solid #e5eaf1;border-radius:9px;padding:20px 22px;min-height:144px}.metric-top{display:flex;justify-content:space-between;align-items:center;color:#758196;font-size:12px}.metric-icon{width:31px;height:31px;border-radius:8px;display:flex;align-items:center;justify-content:center;background:#eff4fe;color:#6388d4}.metric-icon.purple{background:#f3f1fb;color:#9b8dc5}.metric-icon.orange{background:#fcf4e9;color:#ca9f61}.metric-icon.green{background:#edf7f2;color:#78a08d}.metric-number{font-size:27px;font-weight:550;color:#27364d;margin-top:10px;letter-spacing:.2px}.metric-note{font-size:10px;color:#a2acbb;margin-top:12px}.dashboard-middle{display:grid;grid-template-columns:minmax(0,1.42fr) minmax(0,1fr);gap:20px}.dashboard-middle>.panel{min-height:325px}.trend-chart{height:238px;min-width:0}.trend-panel{position:relative}.chart-empty{text-align:center;font-size:11px;color:#9ba7b8;margin:0}.text-link{font-size:11px}.production-list article{padding:9px 0 16px}.production-list article+article{border-top:1px solid #f0f3f7}.production-top{display:flex;justify-content:space-between;gap:12px}.plain-link{padding:0;border:0;background:none;text-align:left;color:#4d617d;font-size:12px;cursor:pointer}.plain-link:hover{color:#3b6fdb}.production-caption{font-size:10px;color:#97a3b5;display:flex;justify-content:space-between;gap:8px;margin:9px 0}.production-caption>span{max-width:70%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.stage-track{display:flex;gap:4px}.stage-track>span{height:4px;background:#edf1f7;flex:1;border-radius:2px}.stage-track>span.done{background:#7498df}.dashboard-bottom{display:grid;grid-template-columns:minmax(260px,.7fr) minmax(0,1.7fr);gap:20px}.todo-list>button{display:flex;align-items:center;gap:12px;padding:16px 0;width:100%;border:0;background:none;text-align:left;border-bottom:1px solid #f0f3f7;font-size:12px;color:#6e7d91}.todo-list>button>strong{margin-left:auto;color:#526a8f;font-size:14px;font-weight:500}.todo-dot{width:7px;height:7px;background:#83a1d9;border-radius:50%}.warning-summary{margin-top:20px;display:flex;justify-content:space-between;align-items:center;font-size:11px}.warning-summary>div{display:flex;align-items:center;gap:9px}.warning-summary strong{font-size:16px;color:#c99c54}.warning-items>div{display:flex;justify-content:space-between;gap:10px;font-size:10px;color:#7c8a9c;margin-top:12px}.warning-items small{color:#a3acb9;display:block;margin-top:3px}.recent-panel{min-width:0}.recent-panel .el-table{font-size:12px}.order-link{font-size:11px;max-width:215px;white-space:nowrap;text-overflow:ellipsis;overflow:hidden;display:block}.order-kind{display:block;font-size:10px;color:#a2acba;margin-top:5px}.dashboard-note{font-size:10px;margin:0}@media(max-width:1200px){.dashboard-middle,.dashboard-bottom{grid-template-columns:1fr}.dashboard-range{flex-direction:column}.dashboard-date{max-width:100%}.dashboard-date .el-date-editor{width:270px}}@media(max-width:700px){.metric-card{padding:15px;min-height:125px}.metric-number{font-size:21px}.metric-note{font-size:9px}.dashboard-date{flex-wrap:wrap}.metric-top{font-size:11px}.metric-icon{width:25px;height:25px}.dashboard-header h1{font-size:23px}}</style>
